pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(t1 > block.timestamp && t2 > t1 + 1);

        vm.roll(bound(uint256(t1), 0, type(uint256).max));
        vm.warp(t1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // General rule: after a successful call at time t1, pastBlockTime == t1.
        assertTrue(c.pastBlockTime() == t1);

        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // The rule must hold for every call: pastBlockTime always reflects the last call's timestamp.
        assertTrue(c.pastBlockTime() == t2);
    }
}

