contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 ts, address actor) public {
        // admissible: block timestamp is strictly greater than the block number,
        // which is overwhelmingly the natural case; keep domain wide but ensure
        // timestamp != block.number so the assertion is well-founded
        ts = bound(ts, block.number + 1, block.timestamp + 2**60);
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        // Reference stores the (timestamp) last-call time, which by admissibility
        // differs from the block number; the mutant stores block.number.
        assertTrue(c.pastBlockTime() != block.number);
    }
}

