pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 blockNum, uint256 ts, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        blockNum = bound(blockNum, 15, type(uint256).max - 1);
        ts = bound(ts, 1, type(uint256).max - 1);
        // pick any block; the rule must hold on every admissible block
        vm.roll(blockNum);
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        if (blockNum % 15 == 0 && ok) {
            // On payout blocks the whole balance is transferred out to the caller.
            assertTrue(address(c).balance == 0);
        } else {
            // On non-payout blocks (or reverts) the balance only ever grows by deposits.
            assertTrue(address(c).balance == 10 ether || address(c).balance == 20 ether || !ok);
        }
    }
}

