pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(address(this), 30 ether);
        caller = (new Caller){value: 20 ether}();

        // first call at t1
        vm.warp(t1);
        bool ok1 = caller.attempt(payable(address(c)));
        // admissible first call succeeds (value is always 10 ether)
        assertTrue(ok1, "first call should succeed");

        // second call at t2 with a (possibly equal/earlier) timestamp
        vm.warp(t2);
        bool ok2 = caller.attempt(payable(address(c)));

        // general rule: success requires a strictly later timestamp than the recorded one
        if (t2 <= t1) {
            assertTrue(!ok2, "call at non-later timestamp must revert");
        } else {
            assertTrue(ok2, "call at strictly later timestamp should succeed");
        }
    }
}

contract Caller {
    constructor() payable {}

    function attempt(address payable c) external returns (bool) {
        (bool ok, ) = c.call{value: 10 ether}("");
        return ok;
    }

    receive() external payable {}
}

